/**
 * SystemMedia is optional and acquires nothing until a Ready main-page owner
 * explicitly configures it. Binding generation only describes the contract.
 */
export const SystemMedia = {
  clear(generation: number, revision: number): Promise<void> {
    return call("SystemMedia.Clear", generation, revision);
  },
  /**
   * Configure claims with generation=0, then requires the last returned generation.
   * Serialize shell mutations. Subscribe before configuring; discard queued events
   * unless generation, revision and trackId all match the frontend's current song.
   */
  configure(generation: number, mediaEnabled: boolean, preventSleep: boolean): Promise<SystemMediaStatus> {
    return call("SystemMedia.Configure", generation, mediaEnabled, preventSleep);
  },
  /**
   * Set consumes an increasing revision even for unsupported/invalid metadata.
   * Revisions must be allocated before any asynchronous preparation. Artwork uses
   * the separately targeted SetArtwork API; URLs and filesystem paths are never accepted.
   */
  set(generation: number, revision: number, track: SystemMediaTrack): Promise<void> {
    return call("SystemMedia.Set", generation, revision, track);
  },
  /**
   * SetArtwork targets an already accepted snapshot. Allocate revision before
   * preparing artwork; a later song, configuration or owner rejects this result.
   * base64 is raw standard padded PNG/JPEG data, never a URL, data URL or path.
   * An empty string clears only the current snapshot's artwork.
   */
  setArtwork(generation: number, revision: number, trackID: string, base64: string): Promise<void> {
    return call("SystemMedia.SetArtwork", generation, revision, trackID, base64);
  },
  /**
   * SetPlayback is for actual play/pause/stop or jumps, never each progress tick.
   * The system advances position while playing; report HTMLAudio's accepted state.
   */
  setPlayback(generation: number, revision: number, trackID: string, state: string, positionMS: number): Promise<void> {
    return call("SystemMedia.SetPlayback", generation, revision, trackID, state, positionMS);
  },
  teardown(generation: number): Promise<void> {
    return call("SystemMedia.Teardown", generation);
  },
} as const;

/** Taskbar shares the Ready main-page owner; construction never touches native APIs. */
export const Taskbar = {
  begin(): Promise<number> {
    return call("Taskbar.Begin");
  },
  /**
   * Sync acknowledges acceptance. Native application can complete later when COM
   * reenters; only completion opens the command gate. An accepted native failure
   * emits desktop:taskbar-failure with the matching epoch and sequence.
   */
  sync(state: TaskbarState): Promise<void> {
    return call("Taskbar.Sync", state);
  },
  teardown(epoch: number): Promise<void> {
    return call("Taskbar.Teardown", epoch);
  },
} as const;

/**
 * Updates methods only enqueue short authorization/state work and return immediately.
 * RPC completion means queued, not authorized/successful. Subscribe to desktop:updates
 * before Begin and wait for its event before issuing commands with the returned epoch.
 * No background checker or installation runs until explicitly requested.
 */
export const Updates = {
  begin(requestID: number): Promise<void> {
    return call("Updates.Begin", requestID);
  },
  /**
   * Cancel requests cancellation without releasing the installation fence. The SDK
   * result decides whether cancellation succeeded or the update was already applied.
   */
  cancel(requestID: number, epoch: number, revision: number): Promise<void> {
    return call("Updates.Cancel", requestID, epoch, revision);
  },
  check(requestID: number, epoch: number, revision: number): Promise<void> {
    return call("Updates.Check", requestID, epoch, revision);
  },
  /**
   * Download is deliberately unsupported: the pinned SDK exposes only a combined
   * signed download + replacement operation. This method never starts that operation.
   */
  download(requestID: number, epoch: number, revision: number): Promise<void> {
    return call("Updates.Download", requestID, epoch, revision);
  },
  getState(requestID: number, epoch: number): Promise<void> {
    return call("Updates.GetState", requestID, epoch);
  },
  /**
   * Install applies the current candidate using SDK signature verification. There is
   * no restart here and no promise that cancellation can prevent disk replacement.
   */
  install(requestID: number, epoch: number, revision: number): Promise<void> {
    return call("Updates.Install", requestID, epoch, revision);
  },
  /**
   * Restart only follows an explicitly requested, completed installation. Its ack
   * is published before the separately queued native relaunch is allowed to run.
   */
  restart(requestID: number, epoch: number, revision: number): Promise<void> {
    return call("Updates.Restart", requestID, epoch, revision);
  },
  teardown(requestID: number, epoch: number): Promise<void> {
    return call("Updates.Teardown", requestID, epoch);
  },
} as const;

